<script setup lang="ts">
import {onMounted, ref} from 'vue'
import UiIcon from './UiIcon.vue'
import type {Locale} from './i18n'
import {translate} from './i18n'
import {createApi, ApiError} from './api'
import {commandKey} from './deposit'

const props=defineProps<{service:ReturnType<typeof createApi>;locale:Locale}>()
const emit=defineEmits<{back:[];registered:[phone:string]}>()
const phone=ref(''),password=ref(''),confirmation=ref(''),referral=ref(''),sourceNonce=ref(''),busy=ref(false),error=ref('')
const t=(key:'phone'|'password'|'phonePlaceholder'|'passwordPlaceholder'|'loading')=>translate(props.locale,key)
function message(e:unknown){error.value=e instanceof ApiError&&e.message==='phone_already_registered'?'手机号已注册':e instanceof ApiError&&(e.message==='inviter_unavailable'||e.message==='inviter_required')?'推荐码无效或缺失':e instanceof ApiError&&e.message==='registration_form_expired'?'注册页面已过期，请重新打开':e instanceof ApiError&&e.message==='password_confirmation_mismatch'?'两次密码不一致':'注册失败，请检查输入后重试'}
async function load(){try{const refCode=new URLSearchParams(location.search).get('ref')||undefined;const form=await props.service.request<{source_nonce:string;referral_code?:string}>('/auth/register/form'+(refCode?'?ref='+encodeURIComponent(refCode):''));sourceNonce.value=form.source_nonce;if(form.referral_code)referral.value=form.referral_code}catch(e){message(e)}}
async function submit(){if(busy.value)return;error.value='';if(!/^1[3-9][0-9]{9}$/.test(phone.value)||!/^[!-~]{8,16}$/.test(password.value)||password.value!==confirmation.value||!referral.value.trim()||!sourceNonce.value){error.value='请填写手机号、密码、确认密码和推荐码';return}busy.value=true;try{await props.service.request('/auth/register',{phone:'+86'+phone.value,password:password.value,password_confirmation:confirmation.value,source_nonce:sourceNonce.value,referral_code:referral.value||undefined},{'Idempotency-Key':commandKey()});emit('registered',phone.value)}catch(e){message(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<div class="reference-surface reference-login"><header class="fixed top-0 w-full z-50 pt-safe bg-surface/80 backdrop-blur-xl shadow-[0_1px_8px_rgba(0,0,0,0.04)]"><div class="h-14 px-margin-sm flex items-center"><button class="min-h-11 px-3 rounded-lg text-primary" type="button" @click="emit('back')"><UiIcon :size="18" name="arrow_back"/> 返回登录</button></div></header><main class="flex flex-col relative w-full pt-14 pb-safe bg-surface min-h-screen"><div class="flex flex-col w-full px-margin-sm pb-space-xl"><div class="flex flex-col items-center text-center mt-space-lg mb-space-lg"><img alt="九合创投" class="w-16 h-16 rounded-full shadow-md" src="/brand.png"/><h1 class="font-headline-lg text-headline-lg font-semibold mt-3">创建账户</h1><p class="font-body-sm text-outline mt-1">创建账户后可直接登录 APP</p></div><form autocomplete="off" class="bg-surface-container-lowest rounded-xl p-space-md shadow-sm space-y-space-md" @submit.prevent="submit"><p v-if="error" class="error" role="alert">{{error}}</p><label class="block space-y-1"><span>{{t('phone')}}</span><input v-model="phone" autocomplete="off" class="w-full h-12 rounded-lg bg-surface-container-low px-3" inputmode="numeric" maxlength="11" :placeholder="t('phonePlaceholder')"/></label><label class="block space-y-1"><span>{{t('password')}}</span><input v-model="password" autocomplete="new-password" class="w-full h-12 rounded-lg bg-surface-container-low px-3" type="password" maxlength="16" :placeholder="t('passwordPlaceholder')"/></label><label class="block space-y-1"><span>确认密码</span><input v-model="confirmation" autocomplete="new-password" class="w-full h-12 rounded-lg bg-surface-container-low px-3" type="password" maxlength="16" placeholder="请再次输入登录密码"/></label><label class="block space-y-1"><span>推荐码 <b class="text-error">*</b></span><input v-model="referral" autocomplete="off" class="w-full h-12 rounded-lg bg-surface-container-low px-3" maxlength="16" placeholder="请输入推荐码" required/></label><button :disabled="busy" class="w-full h-12 rounded-lg text-white font-semibold" style="background-color:rgb(217,119,6)" type="submit">{{busy?t('loading'):'创建账户'}}</button></form></div></main></div>
</template>
